-- ==========================================================
-- CƠ SỞ DỮ LIỆU CHUẨN FIXNEAR (MYSQL / MARIADB)
-- Tech Stack: HTML5, CSS3, JavaScript, PHP 8.x, MySQL
-- Tự động tương thích 100% với XAMPP phpMyAdmin / Laragon
-- ==========================================================

CREATE DATABASE IF NOT EXISTS `fixnear_db` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `fixnear_db`;

-- 1. BẢNG USERS
DROP TABLE IF EXISTS `users`;
CREATE TABLE `users` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `name` VARCHAR(150) NOT NULL,
  `email` VARCHAR(150) NOT NULL UNIQUE,
  `password` VARCHAR(255) NOT NULL,
  `role` ENUM('admin', 'user') DEFAULT 'user',
  `phone` VARCHAR(50) DEFAULT NULL,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- 2. BẢNG SHOPS (68 Cửa Hàng Tại TP.HCM)
DROP TABLE IF EXISTS `shops`;
CREATE TABLE `shops` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `name` VARCHAR(255) NOT NULL,
  `address` VARCHAR(255) NOT NULL,
  `ward` VARCHAR(100) NOT NULL,
  `district` VARCHAR(100) NOT NULL,
  `phone` VARCHAR(50) NOT NULL,
  `opening_hours` VARCHAR(100) DEFAULT '08:00 - 21:00',
  `map_url` TEXT,
  `latitude` DECIMAL(10, 6) DEFAULT 10.853800,
  `longitude` DECIMAL(10, 6) DEFAULT 106.626300,
  `description` TEXT,
  `google_rating` DECIMAL(2, 1) DEFAULT 4.5,
  `google_reviews_count` INT DEFAULT 100,
  `devices` VARCHAR(150) DEFAULT 'laptop,phone',
  `is_verified` TINYINT(1) DEFAULT 1,
  `allows_onsite_watch` TINYINT(1) DEFAULT 1,
  `requires_component_signing` TINYINT(1) DEFAULT 1,
  `student_discount` VARCHAR(255) DEFAULT NULL,
  `image` TEXT,
  `website` VARCHAR(255) DEFAULT NULL,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- 3. BẢNG SERVICES (18 Nhóm Dịch Vụ Sửa Chữa Chuẩn)
DROP TABLE IF EXISTS `services`;
CREATE TABLE `services` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `name` VARCHAR(150) NOT NULL,
  `device_type` VARCHAR(50) NOT NULL,
  `devices` VARCHAR(150) DEFAULT NULL,
  `icon` VARCHAR(50) DEFAULT 'tool',
  `description` TEXT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- 4. BẢNG SHOP_SERVICES (Bảng Giá & Dịch Vụ Chi Tiết Từng Cửa Hàng)
DROP TABLE IF EXISTS `shop_services`;
CREATE TABLE `shop_services` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `shop_id` INT NOT NULL,
  `service_id` INT NOT NULL,
  `min_price` INT DEFAULT 0,
  `max_price` INT DEFAULT 0,
  `warranty_text` VARCHAR(100) DEFAULT '6 - 12 tháng',
  `turnaround_text` VARCHAR(100) DEFAULT '30 - 60 phút',
  `note` TEXT,
  INDEX `idx_shop` (`shop_id`),
  INDEX `idx_service` (`service_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- 5. BẢNG REPAIR_REQUESTS (Hồ Sơ Yêu Cầu Báo Giá & Đặt Lịch Sửa Chữa)
DROP TABLE IF EXISTS `repair_requests`;
CREATE TABLE `repair_requests` (
  `id` VARCHAR(30) PRIMARY KEY,
  `customer_name` VARCHAR(150) NOT NULL,
  `customer_email` VARCHAR(150) DEFAULT NULL,
  `customer_phone` VARCHAR(50) NOT NULL,
  `device_type` VARCHAR(100) NOT NULL,
  `brand_model` VARCHAR(150) DEFAULT NULL,
  `issue_type` VARCHAR(200) DEFAULT NULL,
  `symptom` TEXT,
  `district` VARCHAR(100) DEFAULT NULL,
  `preferred_time` VARCHAR(100) DEFAULT NULL,
  `estimated_price` VARCHAR(150) DEFAULT NULL,
  `status` ENUM('pending', 'contacted', 'completed', 'cancelled') DEFAULT 'pending',
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- 6. BẢNG REVIEWS (Đánh Giá Minh Bạch Của Sinh Viên & Khách Hàng)
DROP TABLE IF EXISTS `reviews`;
CREATE TABLE `reviews` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `shop_id` INT NOT NULL,
  `user_id` INT DEFAULT NULL,
  `user_name` VARCHAR(150) NOT NULL,
  `rating` INT NOT NULL DEFAULT 5,
  `device_name` VARCHAR(150) DEFAULT NULL,
  `service_repaired` VARCHAR(200) DEFAULT NULL,
  `comment` TEXT NOT NULL,
  `is_hidden` TINYINT(1) DEFAULT 0,
  `admin_reply` TEXT DEFAULT NULL,
  `admin_reply_at` DATETIME DEFAULT NULL,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  INDEX `idx_shop_review` (`shop_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- 7. BẢNG WRONG_INFO_REPORTS (Báo Cáo Thông Tin Sai Lệch Từ Cộng Đồng)
DROP TABLE IF EXISTS `wrong_info_reports`;
CREATE TABLE `wrong_info_reports` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `shop_id` INT NOT NULL,
  `shop_name` VARCHAR(200) DEFAULT NULL,
  `user_id` INT DEFAULT NULL,
  `user_name` VARCHAR(150) DEFAULT 'Khách vãng lai',
  `reporter_phone` VARCHAR(50) DEFAULT NULL,
  `reason` VARCHAR(255) NOT NULL,
  `details` TEXT,
  `status` ENUM('pending', 'resolved') DEFAULT 'pending',
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- 8. BẢNG CONTACT_MESSAGES (Tin Nhắn Liên Hệ Hợp Tác)
DROP TABLE IF EXISTS `contact_messages`;
CREATE TABLE `contact_messages` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `name` VARCHAR(150) NOT NULL,
  `email` VARCHAR(150) NOT NULL,
  `phone` VARCHAR(50) DEFAULT NULL,
  `subject` VARCHAR(255) NOT NULL,
  `message` TEXT NOT NULL,
  `status` VARCHAR(20) DEFAULT 'pending',
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 9. BẢNG FAVORITES (Cửa Hàng Yêu Thích Của Người Dùng)
DROP TABLE IF EXISTS `favorites`;
CREATE TABLE `favorites` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `user_id` INT NOT NULL,
  `shop_id` INT NOT NULL,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  UNIQUE KEY `idx_user_shop` (`user_id`, `shop_id`),
  FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON DELETE CASCADE,
  FOREIGN KEY (`shop_id`) REFERENCES `shops`(`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



